/bin/bash -lc "cp data/books.json /tmp/folio-books-backup.json
node --input-type=module <<'JS'
import { readFile } from 'node:fs/promises';
const origin = 'http://localhost:3100';
const page = await (await fetch("'`${origin}/books/new`)).text();
const hidden = [...page.matchAll(/<input type="hidden" name="([''^"]+)"(?: value="([''^"]*)")?'"\\s*\\/>/g)];
const fields = new FormData();
for (const [, name, raw = ''] of hidden) fields.append(name, raw.replaceAll('&quot;', '\"').replaceAll('&amp;', '&'));
fields.append('title', 'The Test Book');
fields.append('author', 'Example Author');
fields.append('notes', 'A note saved with this book.');
const response = await fetch("'`${origin}/books/new`, { method: '"'POST', body: fields });
const books = JSON.parse(await readFile('data/books.json', 'utf8'));
console.log(JSON.stringify({ status: response.status, url: response.url, books }, null, 2));
JS"

/bin/bash -lc "node --input-type=module <<'JS'
import { readFile } from 'node:fs/promises';
const origin = 'http://localhost:3100';
const [book] = JSON.parse(await readFile('data/books.json', 'utf8'));
const page = await (await fetch("'`${origin}/books/${book.id}`)).text();
if (!page.includes(book.title) || !page.includes(book.author) || !page.includes(book.notes)) throw new Error('"'Book details missing');
const fields = new FormData();
for (const [, name, raw = ''] of page.matchAll(/<input type=\"hidden\" name=\"(["'^"]+)"(?: value="([''^"]*)")?'"\\s*\\/>/g)) {
  fields.append(name, raw.replaceAll('&quot;', '\"').replaceAll('&amp;', '&'));
}
const response = await fetch("'`${origin}/books/${book.id}`, { method: '"'POST', body: fields });
const [saved] = JSON.parse(await readFile('data/books.json', 'utf8'));
const home = await (await fetch(origin)).text();
console.log(JSON.stringify({ detailHasNotes: true, finishStatus: response.status, finishUrl: response.url, savedStatus: saved.status, finishedAt: saved.finishedAt, homeHasFinished: home.includes('Finished books') && home.includes(book.title) }, null, 2));
JS"

/bin/bash -lc "node --input-type=module <<'JS'
