const [book] = JSON.parse(await readFile('data/books.json', 'utf8'));
const response = await fetch("'`http://localhost:3100/books/${book.id}`);
const page = await response.text();
console.log(JSON.stringify({status: response.status, titlePersists: page.includes(book.title), notePersists: page.includes(book.notes), finishedPersists: page.includes('"'Finished')}, null, 2));
await copyFile('/tmp/folio-books-backup.json', 'data/books.json');
JS"
